program='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr,nc))
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    colors = {3: 8, 5: 4, 7: 3}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or outside[r][c] or seen[r][c]:
                continue
            comp = []
            q.append((r,c)); seen[r][c] = True
            while q:
                rr, cc = q.popleft(); comp.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc] and not seen[nr][nc]:
                        seen[nr][nc] = True; q.append((nr,nc))
            side = max(max(rr for rr,cc in comp)-min(rr for rr,cc in comp)+1, max(cc for rr,cc in comp)-min(cc for rr,cc in comp)+1)
            color = colors[side]
            for rr,cc in comp: out[rr][cc] = color
    return out
'''
